// Illustrative local state only. Nothing here connects to Minecraft or an API.
const state={screen:'jobs',jobs:[{name:'Gather oak logs',detail:'Resource trip · 8 of 24 earned',status:'In progress'},{name:'Build meadow workshop',detail:'Waiting for approved design and supplies',status:'Waiting'},{name:'Sort stone chest',detail:'Storage permission required',status:'Waiting'}],paused:false,layout:false,approved:false,rotation:0,position:0,material:'Oak planks',supply:0,raw:0,cobble:64,trip:true,progress:8,design:0,variant:0,revised:false,asking:false,share:false,imported:false,permission:false,power:false,fluid:false,search:'',revision:'',personality:'Practical and friendly',message:''};
const $=s=>document.querySelector(s);
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,extra='')=>`<button data-action="${action}" ${extra}>${label}</button>`;
function render(){
 const active=document.activeElement, action=active?.dataset.action, id=active?.id, inContent=$('#content').contains(active);
 document.querySelectorAll('nav button').forEach(b=>{let active=b.dataset.screen===state.screen;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
 const pages={jobs,build,blueprints,production,settings};$('#content').innerHTML=pages[state.screen]();
 if(inContent){let target=id&&document.getElementById(id); if(!target&&action){let fallback=action.startsWith('preview:')?'rotate':action==='approve'?'start':action==='layout'?'approve':action==='triprecall'?'craft':null;target=[...document.querySelectorAll('[data-action]')].find(b=>b.dataset.action===action&&!b.disabled)||[...document.querySelectorAll('[data-action]')].find(b=>b.dataset.action===fallback&&!b.disabled)} (target||document.querySelector('nav .active')).focus({preventScroll:true})}
}
function syncJobs(){state.jobs.forEach((j,i)=>j.status=i===0&&!(j.name==='Gather oak logs'&&!state.trip)?'In progress':'Waiting')}
function endTrip(){if(!state.trip)return 0;const earned=state.progress;state.raw+=earned;state.progress=0;state.trip=false;return earned}
function recallTrip(){if(!state.trip){state.message='No resource trip is active.';return}let earned=endTrip();state.message=`Rowan returned with ${earned} oak logs earned on the simulated trip.`}
function jobs(){return `<div class="layout"><div><section class="panel"><div class="panelhead"><div><h2>Rowan</h2><p class="muted small">Your companion · Meadow work zone</p></div><strong class="${state.paused?'status':'ok'}">${state.paused?'PAUSED':'WORKING'}</strong></div><div class="inset"><strong>${state.paused?'Work paused':state.trip?'On a resource trip':'At home'}</strong><p class="muted small">${state.trip?`Simulated trip · ${state.progress} oak logs earned so far`:'No active resource trip'}</p></div><div class="actions">${button('pause',state.paused?'Resume work':'Pause work','class="primary"')}${button('recall','Recall Rowan')}${button('stop','Stop current job','class="danger"')}</div><p class="small muted" style="margin-top:10px">Recall returns partial earned materials. No undo: request a correction after stopping work.</p></section><section class="panel"><div class="panelhead"><div><h3>Carried inventory</h3><p class="small muted">Unlimited carrying · illustrative</p></div></div><div class="inventory"><div class="slot"><b>${state.raw}</b>Oak logs</div><div class="slot"><b>32</b>Stone</div><div class="slot"><b>12</b>Coal</div><div class="slot"><b>1</b>Iron axe</div></div><p class="small muted" style="margin-top:10px">Axe durability: 64% · Replacement uses real materials.</p></section></div><section class="panel"><div class="panelhead"><div><h2>Job queue</h2><p class="muted">Rowan works through these in order.</p></div><span class="small">${state.jobs.length} jobs</span></div><div class="stack">${state.jobs.map((j,i)=>`<div class="queue-item ${i===0?'selected':''}"><div class="row between"><strong>${i+1}. ${escapeHTML(j.name)}</strong><span class="${i===0?'ok':'status'} small">${j.name==='Gather oak logs'&&!state.trip?'Returned':i===0&&state.paused&&j.status==='In progress'?'Paused':j.status}</span></div><div class="small muted">${escapeHTML(j.name==='Gather oak logs'?(state.trip?`Resource trip · ${state.progress} of 24 earned`:`Resource trip ended · ${state.raw} logs carried`):j.detail)}</div><div class="row">${button('up:'+i,'Move up',`class="tinybtn" ${i===0?'disabled':''}`)}${button('down:'+i,'Move down',`class="tinybtn" ${i===state.jobs.length-1?'disabled':''}`)}${button('cancel:'+i,'Cancel job','class="tinybtn"')}</div></div>`).join('')||'<p class="inset">The queue is empty.</p>'}</div><div class="summary" style="margin-top:14px"><strong>New order during work</strong><p class="small muted">Choose whether to queue it or switch; Rowan will not silently interrupt an active job.</p><div class="actions">${button('queue','Queue sample order')}${button('switch','Switch to sample order')}</div></div><p class="log" role="status">${escapeHTML(state.message)}</p></section></div>`}
function build(){let ready=state.supply>=24;return `<div class="panelhead"><div><h2>${items[state.design][0]}</h2><p class="muted">Settlement plan / Building 1 of 3 · illustrative draft</p></div><span class="status">${state.approved?'DESIGN APPROVED':'REVIEW REQUIRED'}</span></div><div class="layout"><div><section class="panel"><div class="panelhead"><div><h3>Ghost preview</h3><p class="muted small">Position ${state.position} · Rotation ${state.rotation}° · ${escapeHTML(state.material)}</p></div></div><div class="world" aria-label="Illustrative ghost preview of ${items[state.design][0]}"><span class="ghost-label">GHOST · NOT BUILT</span><div class="house design-${state.design} variant-${state.variant} ${state.material==='Stone bricks'?'stone':''} ${state.revised?'revised':''}" style="--turn:${[0,40,180,220][state.rotation/90]}deg;--shift:${(state.position%5)*12}px"><span class="window"></span></div></div><div class="actions">${button('rotate','Rotate 90°')}${button('move','Move site +1')}${button('alternate','Alternative design')}</div><p class="small muted" style="margin-top:8px">Changes require a fresh individual approval.</p><p class="summary small" style="margin-top:10px"><strong>${ready?'Supplies complete':`Shortage: ${24-state.supply} ${escapeHTML(state.material)}`}</strong> · ${!state.layout?'Approve the layout first.':ready?'Review and approve this building.':state.material==='Stone bricks'?'Ask the player for stone bricks.':'Gather logs or ask the player for supplies.'}</p></section><section class="panel"><h3>Revise the draft</h3><label for="material">Wall material</label><select id="material"><option ${state.material==='Oak planks'?'selected':''}>Oak planks</option><option ${state.material==='Stone bricks'?'selected':''}>Stone bricks</option></select><label for="revision" style="margin-top:10px">Describe a revision</label><textarea id="revision" placeholder="For example: add a larger doorway">${escapeHTML(state.revision)}</textarea><div class="actions">${button('revise','Apply simulated revision')}</div></section></div><div><section class="panel"><h3>Approval sequence</h3><div class="stack" style="margin-top:10px"><div class="inset"><strong>1. Settlement layout</strong><p class="small ${state.layout?'ok':'status'}">${state.layout?'Approved':'Awaiting approval'}</p><div class="actions">${button('layout','Approve layout',state.layout?'disabled':'')}</div></div><div class="inset"><strong>2. This building & materials</strong><p class="small ${state.approved?'ok':'status'}">${state.approved?'Approved':'Requires layout approval and all listed supplies'}</p><div class="actions">${button('approve','Approve this building',`class="primary" ${!state.layout||!ready||state.approved?'disabled':''}`)}</div></div><div class="inset"><strong>3. Start building</strong><p class="small ${ready&&state.approved?'ok':'status'}">${ready&&state.approved?'Ready: all supplies available':'Blocked until design approved and all supplies collected'}</p><div class="actions">${button('start','Start building',`class="primary" ${!ready||!state.approved?'disabled':''}`)}</div></div></div></section><section class="panel"><div class="panelhead"><h3>Materials for this building</h3><span class="status">${ready?'COMPLETE':'SHORTAGE'}</span></div><table class="table"><thead><tr><th>Material</th><th>Available / needed</th></tr></thead><tbody><tr><td>${escapeHTML(state.material)}</td><td>${state.supply} / 24</td></tr><tr><td>Cobblestone</td><td>${state.cobble} / 40</td></tr><tr><td>Glass panes</td><td>8 / 8</td></tr></tbody></table><p class="small muted" style="margin-top:10px">Choose a supply source. Gather trips yield oak logs only; processing is a separate simulated step.</p><div class="actions">${button('ask','Ask player for supplies')}${state.material==='Oak planks'?button('gather',state.trip?'Trip in progress':'Gather oak logs',state.trip||ready?'disabled':''):''}${state.material==='Oak planks'?button('craft','Craft planks from logs',state.raw===0||ready?'disabled':''):''}</div>${state.trip?`<p class="small status" style="margin-top:8px">Trip: ${state.progress} / 24 oak logs earned · owner online</p><div class="actions">${button('advance','Advance simulated trip',state.paused?'disabled':'')}${button('triprecall','Recall with partial')}</div>`:''}<p class="small muted">Carried oak logs: ${state.raw} · ${state.material==='Oak planks'?'1 log → 1 demo plank (illustrative rate).':'Stone bricks must be supplied by the player in this demo.'}</p>${state.asking?`<div class="actions">${button('deliver','Simulate player delivery')}</div>`:''}<p class="log" role="status">${escapeHTML(state.message)}</p></section></div></div>`}
const items=[['Meadow workshop','Built-in','Small workshop · 9 × 7'],['Riverside cottage','Personal','Saved AI design · 11 × 9'],['Stone storehouse','Public','Admin-reviewed · 13 × 9']];
function blueprints(){let matches=items.filter(x=>x.join(' ').toLowerCase().includes(state.search.toLowerCase()));return `<div class="panelhead"><div><h2>Blueprint library</h2><p class="muted">Choose a design to discuss and preview before building.</p></div><span class="small">ILLUSTRATIVE CATALOG</span></div><div class="layout"><section class="panel"><h3>Find a blueprint</h3><label for="search">Search library</label><input id="search" type="search" value="${escapeHTML(state.search)}" placeholder="Name or source"><p class="small muted" style="margin-top:12px">Built-in, personal and approved public designs appear here. Imported blocks may need approved replacements.</p><hr class="rule"><h3>Admin imports</h3><p class="small muted">Admins install schematics. Missing blocks require proposed replacements and approval.</p><div class="actions">${button('import','Simulate admin import')}</div><p class="log" role="status">${state.imported?'Example import queued for admin review; no file imported.':''}</p></section><section class="panel"><div class="panelhead"><h3>Designs</h3><span class="small">${matches.length} results</span></div><div class="catalog">${matches.map(x=>`<article class="blueprint"><div class="thumb thumb-${items.indexOf(x)}" aria-hidden="true"></div><strong>${x[0]}</strong><p class="small ok">${x[1]}</p><p class="small muted">${x[2]}</p><div class="actions">${button('preview:'+items.indexOf(x),'Preview','class="tinybtn"')}${x[1]==='Personal'?button('share',state.share?'Submitted':'Request sharing',`class="tinybtn" ${state.share?'disabled':''}`):''}</div></article>`).join('')||'<p>No matching designs. Try another search.</p>'}</div><p class="small muted" style="margin-top:14px">${state.share?'Sharing request submitted for admin review; it is not public yet.':'Personal designs become public only after admin review.'}</p></section></div>`}
function production(){return `<div class="panelhead"><div><h2>Production chain</h2><p class="muted">Example: workshop glass · proposed compatibility display</p></div><span class="status">BLOCKED</span></div><div class="layout"><section class="panel"><h3>Required inputs</h3><p class="muted small">Materials reserved for approved jobs cannot be spent twice.</p><table class="table" style="margin-top:10px"><thead><tr><th>Resource</th><th>Available / reserved</th></tr></thead><tbody><tr><td>Sand</td><td>16 / 8</td></tr><tr><td>Coal</td><td>12 / 4</td></tr><tr><td>Glass panes</td><td>8 / 8</td></tr></tbody></table><hr class="rule"><h3>Compatibility levels</h3><p class="small"><strong>Recipe discovery:</strong> <span class="ok">Example registered recipe found</span></p><p class="small"><strong>Machine adapter:</strong> <span class="status">Example adapter unverified</span></p><p class="small muted" style="margin-top:8px">Actual machine recipes need a real station and a compatible adapter. Portable crafting cannot bypass power, fluids or progression.</p></section><section class="panel"><div class="panelhead"><div><h3>Ingredient path</h3><p class="small muted">Proposed demo · no machine connected</p></div></div><div class="chain"><div class="step"><strong>1. Sand</strong><span class="ok small">Available · 8 reserved</span></div><div class="step"><strong>2. Process glass</strong><span class="status small">Station & adapter required</span></div><div class="step"><strong>3. Glass panes</strong><span class="small">8 reserved for workshop</span></div></div><hr class="rule"><h3>Machine checks</h3><p class="small muted">Example state controls demonstrate blockers, not real compatibility.</p><div class="stack" style="margin-top:10px"><div class="inset row between"><span>Unfamiliar station permission: <strong>${state.permission?'Granted':'Required'}</strong></span>${button('permission',state.permission?'Revoke':'Grant demo permission','class="tinybtn"')}</div><div class="inset row between"><span>Power: <strong class="${state.power?'ok':'status'}">${state.power?'Demo available':'Blocked · no power'}</strong></span>${button('power','Toggle demo power','class="tinybtn"')}</div><div class="inset row between"><span>Fluid: <strong class="${state.fluid?'ok':'status'}">${state.fluid?'Demo available':'Blocked · missing fluid'}</strong></span>${button('fluid','Toggle demo fluid','class="tinybtn"')}</div></div><p class="log" role="status">${state.permission&&state.power&&state.fluid?'Still blocked: a real station and verified adapter are required.':'Resolve permission and displayed inputs; adapter verification remains required.'}</p></section></div>`}
function settings(){return `<div class="layout"><section class="panel"><h2>Companion preferences</h2><p class="muted">Example settings for Rowan</p><label for="personality" style="margin-top:16px">Personality</label><select id="personality"><option ${state.personality==='Practical and friendly'?'selected':''}>Practical and friendly</option><option ${state.personality==='Quiet and concise'?'selected':''}>Quiet and concise</option><option ${state.personality==='Curious and chatty'?'selected':''}>Curious and chatty</option></select><p class="small muted" style="margin-top:10px">Only the example selection changes here. No AI is connected.</p><hr class="rule"><h3>Memory controls</h3><p class="small muted">Local forgetting would not promise deletion by a remote provider.</p><div class="actions">${button('forget','Simulate forgetting a preference')}</div><p class="log" role="status">${escapeHTML(state.message)}</p></section><section class="panel"><h2>AI connection & privacy</h2><div class="inset" style="margin-top:12px"><strong class="status">Not connected · prototype</strong><p class="small">No key field, storage or API calls are implemented.</p></div><p style="margin-top:14px">The intended model is an owner-provided BharatCode key kept on the owner's computer. The client contacts AI; the server validates actions. The integration route is unverified.</p><p class="small muted" style="margin-top:12px">Only addressed messages and needed task, world and inventory context would be sent after disclosure. Unrelated chat is excluded. Trusted players need explicit permission to use the owner's allowance and never receive the key.</p><hr class="rule"><p class="small">Approved executable jobs and basic controls remain available without AI. Jobs needing a new AI decision pause.</p></section></div>`}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-screen]');if(nav){state.screen=nav.dataset.screen;state.message='';render();return}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;let [a,n]=b.dataset.action.split(':');n=Number(n);state.message='';switch(a){case'pause':state.paused=!state.paused;break;case'recall':recallTrip();break;case'stop':if(state.jobs[0]?.name==='Gather oak logs')endTrip();if(state.jobs.length){state.message='Stopped '+state.jobs[0].name+'. Request corrections explicitly; no undo.';state.jobs.shift()}break;case'up':case'down':{let to=n+(a==='up'?-1:1);if(state.trip&&(n===0||to===0))endTrip();[state.jobs[n],state.jobs[to]]=[state.jobs[to],state.jobs[n]];b.dataset.action=`${a}:${to}`;break}case'cancel':if(state.jobs[n].name==='Gather oak logs'&&state.trip)endTrip();state.message='Cancelled '+state.jobs[n].name+'.';state.jobs.splice(n,1);break;case'queue':state.jobs.push({name:'Deliver stone',detail:'Sample order · pending',status:'Waiting'});state.message='Sample order added to queue.';break;case'switch':if(state.trip)endTrip();state.jobs.unshift({name:'Deliver stone',detail:'Sample order · switched by owner',status:'In progress'});state.message='Switched to the sample order; previous job remains queued.';break;case'rotate':state.rotation=(state.rotation+90)%360;state.approved=false;break;case'move':state.position++;state.approved=false;break;case'alternate':state.variant=(state.variant+1)%2;state.approved=false;state.message='Alternative draft shown; review again.';break;case'revise':state.revision=$('#revision').value;if(state.revision.trim()){state.revised=!state.revised;state.approved=false}state.message=state.revision.trim()?'Revision noted in this simulated draft; review again.':'Enter a revision first.';break;case'layout':state.layout=true;break;case'approve':if(state.layout&&state.supply>=24)state.approved=true;break;case'start':if(state.layout&&state.approved&&state.supply>=24)state.message='Building started in the simulation; no blocks were placed.';break;case'ask':if(state.trip)recallTrip();state.asking=true;state.message='Asked player for supplies.';break;case'gather':if(state.trip)break;state.jobs=state.jobs.filter(j=>j.name!=='Gather oak logs');state.jobs.unshift({name:'Gather oak logs',detail:'Resource trip',status:'In progress'});state.trip=true;state.progress=0;state.asking=false;state.message='Simulated trip started; collecting oak logs only.';break;case'advance':if(!state.trip||state.paused)break;state.progress=Math.min(24,state.progress+8);if(state.progress>=24)recallTrip();break;case'triprecall':recallTrip();break;case'craft':{if(state.material!=='Oak planks')break;let count=Math.min(state.raw,24-state.supply);state.raw-=count;state.supply+=count;state.message=`Processed ${count} oak logs into ${count} ${state.material} (demo rates).`;break}case'deliver':state.supply=24;state.asking=false;state.message='Simulated player delivery received.';break;case'preview':state.design=n;state.variant=0;state.revised=false;state.approved=false;state.screen='build';state.message='Example preview opened; discuss the design before drafting.';break;case'share':state.share=true;break;case'import':state.imported=true;break;case'permission':state.permission=!state.permission;break;case'power':state.power=!state.power;break;case'fluid':state.fluid=!state.fluid;break;case'forget':state.message='Example preference forgotten locally (simulation only).';break}syncJobs();render()});
document.addEventListener('change',e=>{if(e.target.id==='material'){state.material=e.target.value;state.supply=0;state.approved=false;state.message='Material changed; review this building again.';render()}if(e.target.id==='personality'){state.personality=e.target.value;state.message='Example personality changed.';render()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){let pos=e.target.selectionStart;state.search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
render();
